import{_ as e,c as r,o as i,af as h}from"./chunks/framework.BKeRpnBD.js";const _=JSON.parse('{"title":"第二十二卦 贲 山火贲 艮上离下","description":"周易 - 第二十二卦 贲 山火贲 艮上离下","frontmatter":{"title":"第二十二卦 贲 山火贲 艮上离下","description":"周易 - 第二十二卦 贲 山火贲 艮上离下"},"headers":[],"relativePath":"zh/classics/zhouyi/023.md","filePath":"zh/classics/zhouyi/023.md"}'),l={name:"zh/classics/zhouyi/023.md"};function t(n,a,s,d,o,c){return i(),r("div",null,[...a[0]||(a[0]=[h('<h1 id="贲" tabindex="-1">贲 <a class="header-anchor" href="#贲" aria-label="Permalink to “贲”">​</a></h1><h2 id="卦辞" tabindex="-1">卦辞 <a class="header-anchor" href="#卦辞" aria-label="Permalink to “卦辞”">​</a></h2><p>亨。小利有所往。</p><h3 id="彖传" tabindex="-1">彖传 <a class="header-anchor" href="#彖传" aria-label="Permalink to “彖传”">​</a></h3><p>贲，亨；柔来而文刚，故亨。分刚上而文柔，故小利有攸往。天文也；文明以止，人文也。观乎天文，以察时变；观乎人文，以化成天下。</p><h3 id="象传" tabindex="-1">象传 <a class="header-anchor" href="#象传" aria-label="Permalink to “象传”">​</a></h3><p>山下有火，贲；君子以明庶政，无敢折狱。</p><h3 id="初九" tabindex="-1">初九 <a class="header-anchor" href="#初九" aria-label="Permalink to “初九”">​</a></h3><p>贲其趾，舍车而徒。象曰：舍 车而徒，义弗乘也。</p><h3 id="六二" tabindex="-1">六二 <a class="header-anchor" href="#六二" aria-label="Permalink to “六二”">​</a></h3><p>贲其须。象曰：贲其须，与上兴也。</p><h3 id="九三" tabindex="-1">九三 <a class="header-anchor" href="#九三" aria-label="Permalink to “九三”">​</a></h3><p>贲如濡如，永贞吉。象曰：永贞之吉，终莫之陵也。</p><h3 id="六四" tabindex="-1">六四 <a class="header-anchor" href="#六四" aria-label="Permalink to “六四”">​</a></h3><p>贲如皤如，白马翰如，匪寇婚媾。象曰：六四，当位疑也。匪寇婚媾，终无尤也。</p><h3 id="六五" tabindex="-1">六五 <a class="header-anchor" href="#六五" aria-label="Permalink to “六五”">​</a></h3><p>贲于丘园，束帛戋戋，吝，终吉。象曰：六五之吉，有喜也。</p><h3 id="上九" tabindex="-1">上九 <a class="header-anchor" href="#上九" aria-label="Permalink to “上九”">​</a></h3><p>白贲，无咎。象曰：白贲无咎，上得志也。</p>',19)])])}const b=e(l,[["render",t]]);export{_ as __pageData,b as default};
